mapper.select:
SELECT /* kh.com.kbprasac.csu.csm.dao.CommonDao.selectErrorCode */
	    OUTPT_CTNT1 AS "outptCtnt1"
	  , OUTPT_CTNT2 AS "outptCtnt2"
	  , CHNL_DSTCD AS "chnlDstcd"
FROM ${schema}.TSCSM0003 ET		
 WHERE ET.OPER_GROUP_CD = #{operGroupCd}
   AND ET.ERR_MSGCD = #{errorMsgcd}

       AND ET.LANG_DSTCD = #{langDstcd}

SELECT /* kh.com.kbprasac.csu.csm.dao.CommonDao.selectErrorCode */
	    OUTPT_CTNT1 	AS "outptCtnt1"
	  , OUTPT_CTNT2 	AS "outptCtnt2"
	  , CHNL_DSTCD  	AS "chnlDstcd"
	  , MSG_KND_CD_NO 	AS "msgKndCdNo"
FROM ${schema}.TSCSM0003 ET		
 WHERE ET.OPER_GROUP_CD = #{operGroupCd}
   AND ET.ERR_MSGCD IN 

		#{item}



       AND ET.LANG_DSTCD = #{langDstcd}

mapper.update:
UPDATE /* kh.com.kbprasac.csu.lne.cmn.dao.MsgMgtDao.updateMsgMgt */
       ${schema}.TSCSM0003 
   SET 
	   OUTPT_CTNT1 = #{outptCtnt1}
	 , OUTPT_CTNT2 = NVL(#{outptCtnt2}, ' ')
	 , SYS_LAST_PRCSS_YMS = CURRENT_TIMESTAMP
	 , SYS_LAST_UNO = #{sysLastUno}
 WHERE OPER_GROUP_CD = #{operGroupCd}
   AND LANG_DSTCD = #{langDstcd}
   AND ERR_MSGCD = #{errMsgcd}
   AND CHNL_DSTCD = #{chnlDstcd}

mapper.delete:
DELETE /* kh.com.kbprasac.csu.lne.cmn.dao.MsgMgtDao.deleteMsgMgt */ 
  FROM ${schema}.TSCSM0003 
 WHERE OPER_GROUP_CD = #{operGroupCd}
   AND LANG_DSTCD = #{langDstcd}
   AND ERR_MSGCD = #{errMsgcd}
   AND CHNL_DSTCD = #{chnlDstcd}
